/* Aprenem - MEDI, part natural: temari de 6è de Primària
   Part de l'app d'estudi. Vegeu CLAUDE.md per a l'estructura i les normes.
   Fonts:
   - Decret 31/2022, d'1 d'agost, pel qual s'estableix el currículum de l'educació primària a les Illes Balears
     (BOIB núm. 101, de 2-8-2022), modificat pel Decret 18/2025. Àrea de Coneixement del medi natural, social
     i cultural, sabers bàsics del 3r cicle: A. Cultura científica (la vida al nostre planeta: la cèl·lula,
     funcions vitals, aparells, salut; matèria, forces i energia) i B. Tecnologia i digitalització.
     https://www.caib.es/sites/lomloe/es/normativa_de_educacion_primaria
   - Contrastat amb l'estructura habitual dels llibres de Ciències de la naturalesa de 6è (la cèl·lula i els
     regnes, nutrició, relació, reproducció, salut, ecosistemes, matèria i canvis, electricitat i magnetisme, màquines).
   Els temes de 6è porten curs:[6]. Els temes amb làmina són a contingut/lamines/. */
const mdSkill=(nom,ab,errT,teoria,bank,extra)=>Object.assign(bankSkill(nom,'',errT,teoria,mkBank(bank)),{curs:[6],ab,errT},extra||{});
// Barreja un generador propi amb el banc de preguntes (p = probabilitat del generador)
const mdMix=(sk,g,p=.5)=>Object.assign(sk,{gen(lv){if(Math.random()<p){const x=g(lv);if(x)return x}return qProb(pick(sk.bank.filter(q=>lv>0||!q.lv)),sk.errT)},errT:sk.errT});

/* ---------- Els cinc regnes ---------- */
const REGNES=[['el bolet','fongs','és heteròtrof i es reprodueix per espores'],['la floridura del pa','fongs','és un fong microscòpic que creix sobre els aliments'],['el llevat','fongs','és un fong unicel·lular que fa pujar la massa del pa'],['l\'ameba','protoctists','és unicel·lular i té nucli'],['el paramecí','protoctists','és unicel·lular, té nucli i es mou amb cilis'],['l\'alga verda','protoctists','té nucli i fa la fotosíntesi, però no té arrels, tija ni fulles de veritat'],['el bacteri','moneres','és unicel·lular i no té nucli'],['l\'ullastre','plantes','és pluricel·lular i fa la fotosíntesi'],['la falguera','plantes','és pluricel·lular i fa la fotosíntesi'],['la molsa','plantes','és pluricel·lular i fa la fotosíntesi'],['el pop','animals','és pluricel·lular, heteròtrof i es desplaça'],['la medusa','animals','és pluricel·lular, heteròtrof i s\'alimenta d\'altres éssers vius'],['l\'esponja de mar','animals','és pluricel·lular i heteròtrof, encara que no es mou'],['la posidònia','plantes','té arrels, tija i fulles, i fa flors: és una planta, no una alga']];
const RGN={'animals':['animals','animal','regne animal'],'plantes':['plantes','planta','vegetal','vegetals','regne vegetal'],'fongs':['fongs','fong','regne dels fongs'],'protoctists':['protoctists','protoctist','protists','protista'],'moneres':['moneres','monera','bacteris']};
SK.md_regnes=mdMix(mdSkill('Els cinc regnes','Rg','md_regnes',
 ['Els éssers vius es classifiquen en <b>cinc regnes</b>, segons com són les seves cèl·lules i com s\'alimenten.','<b>Animals</b>: pluricel·lulars i heteròtrofs (s\'alimenten d\'altres éssers vius). <b>Plantes</b>: pluricel·lulars i autòtrofes (fan la fotosíntesi).','<b>Fongs</b>: bolets, floridures i llevats; són heteròtrofs, i molts es reprodueixen per espores. <b>Protoctists</b>: algues i protozous (com l\'ameba), amb cèl·lules amb nucli. <b>Moneres</b>: els bacteris, unicel·lulars i <b>sense nucli</b>.','Molts microorganismes ens ajuden (els bacteris del iogurt, els llevats del pa), però alguns provoquen malalties.'],
 [['Quin regne està format per éssers unicel·lulars sense nucli, com els bacteris?','moneres','Són els éssers vius més senzills.','Els bacteris formen el regne de les <b>moneres</b>.','protoctists'],
  ['A quin regne pertanyen els bolets?','fongs|regne dels fongs','No són plantes perquè no fan la fotosíntesi.','Els bolets són <b>fongs</b>: s\'alimenten de restes d\'altres éssers vius.','plantes'],
  ['Quin fong unicel·lular fa servir el forner perquè pugi la massa del pa?','llevat','També s\'usa per fer cervesa.','El <b>llevat</b> és un fong que fermenta la massa i la fa pujar.','bacteri'],
  ['Com es diuen les cèl·lules petites amb què es reprodueixen molts fongs?','espores|espora','Són com «llavors» microscòpiques.','Els fongs es reprodueixen per <b>espores</b>.','llavors'],
  ['Com es diuen els éssers vius que s\'alimenten d\'altres éssers vius, com els animals i els fongs?','heteròtrofs|heteròtrof','Són el contrari dels autòtrofs.','Els animals i els fongs són <b>heteròtrofs</b>.','autòtrofs|autòtrof'],
  ['Quin medicament va descobrir Alexander Fleming a partir d\'una floridura?','penicil·lina','És el primer antibiòtic.','Fleming va descobrir la <b>penicil·lina</b> el 1928, a partir d\'una floridura.','',1],
  ['Quin regne inclou les algues i els protozous?','protoctists|protoctist|protists','Tenen cèl·lules amb nucli però són molt senzills.','Les algues i els protozous són <b>protoctists</b>.','moneres|plantes',1]]),
 lv=>{const[n,g,f]=pick(REGNES);return{text:`A quin regne pertany <b>${n}</b>?`,fields:[{label:'Regne',txt:RGN[g],loose:true,wide:true}],vis:null,
  hints:['Pensa: té nucli? És unicel·lular o pluricel·lular? Fa la fotosíntesi?',`Fixa't: ${f}.`],steps:[`${cap(n)} ${f}.`,`Per tant, pertany al regne <b>${g==='plantes'?'de les plantes':g==='animals'?'dels animals':g==='fongs'?'dels fongs':g==='moneres'?'de les moneres':'dels '+g}</b>.`],
  err:v=>Object.entries(RGN).some(([k,a])=>k!==g&&a.map(fold).includes(fold(v[0])))?'md_regnes':null}},.55);

/* ---------- L'aparell excretor ---------- */
SK.md_excretor=mdSkill('L\'aparell excretor','Ex','md_excretor',
 ['L\'<b>excreció</b> és l\'eliminació de les substàncies de rebuig que fabriquen les cèl·lules. No s\'ha de confondre amb l\'egestió (expulsar la femta).','L\'<b>aparell urinari</b>: els <b>ronyons</b> filtren la sang i fabriquen l\'<b>orina</b>; els <b>urèters</b> la porten a la <b>bufeta urinària</b>, que la guarda; i la <b>uretra</b> la treu a l\'exterior.','Altres òrgans excretors: les <b>glàndules sudorípares</b> de la pell fabriquen la <b>suor</b>, i els <b>pulmons</b> expulsen el diòxid de carboni.','Per tenir cura dels ronyons cal beure prou aigua cada dia.'],
 [['Quins òrgans filtren la sang i fabriquen l\'orina?','ronyons|ronyó','N\'hi ha dos, a l\'esquena, a l\'altura de la cintura.','Els <b>ronyons</b> netegen la sang.','bufeta|fetge'],
  ['Quin òrgan guarda l\'orina fins que anam al bany?','bufeta urinària|bufeta','És com una bossa elàstica.','La <b>bufeta urinària</b> guarda l\'orina.','ronyons|uretra'],
  ['Com es diuen els dos tubs que porten l\'orina dels ronyons a la bufeta?','urèters|urèter','No els confonguis amb la uretra.','Els <b>urèters</b> uneixen els ronyons amb la bufeta.','uretra'],
  ['Com es diu el conducte que treu l\'orina de la bufeta cap a fora?','uretra','És un sol tub.','La <b>uretra</b> porta l\'orina a l\'exterior.','urèters|urèter'],
  ['Quin líquid fabriquen les glàndules sudorípares de la pell?','suor','Surt quan fa calor o feim esport.','La <b>suor</b> elimina substàncies de rebuig i ens refreda.','orina'],
  ['Com es diu la funció d\'eliminar les substàncies de rebuig de les cèl·lules?','excreció','És diferent de l\'egestió.','L\'<b>excreció</b> elimina els residus de la sang.','egestió|digestió'],
  ['Quin gas de rebuig expulsen els pulmons?','diòxid de carboni|CO2','És el gas que expulsam en respirar.','Els pulmons també són excretors: expulsen el <b>diòxid de carboni</b>.','oxigen'],
  ['Quin líquid fabriquen els ronyons?','orina','Es guarda a la bufeta.','Els ronyons fabriquen l\'<b>orina</b> amb aigua i substàncies de rebuig.','suor'],
  ['Com es diuen les unitats petitíssimes dels ronyons que filtren la sang?','nefrones|nefrona','N\'hi ha més d\'un milió a cada ronyó.','Les <b>nefrones</b> són els filtres dels ronyons.','alvèols',1]]);

/* ---------- El sistema nerviós ---------- */
SK.md_nervios=mdSkill('El sistema nerviós','Sn','md_nervios',
 ['La <b>funció de relació</b> ens permet captar el que passa (amb els <b>sentits</b>), decidir què fer (amb el <b>sistema nerviós</b>) i respondre (amb l\'<b>aparell locomotor</b>).','El sistema nerviós està format per <b>neurones</b>, cèl·lules que transmeten missatges elèctrics. Tenen un cos, unes branques curtes (<b>dendrites</b>) i una prolongació llarga (<b>axó</b>).','<b>Sistema nerviós central</b>: l\'<b>encèfal</b> (dins el crani: el <b>cervell</b> pensa, recorda i dona ordres; el <b>cerebel</b> coordina els moviments i l\'equilibri; el <b>tronc encefàlic</b> controla el batec i la respiració) i la <b>medul·la espinal</b> (dins la columna vertebral).','<b>Sistema nerviós perifèric</b>: els <b>nervis</b>, que porten la informació dels sentits al centre (sensitius) i les ordres als músculs (motors).','Els <b>actes voluntaris</b> els decideix el cervell (xutar una pilota). Els <b>actes reflexos</b> són molt ràpids i els controla la medul·la, sense pensar-hi (apartar la mà del foc).'],
 [['Com es diuen les cèl·lules del sistema nerviós?','neurones|neurona','Transmeten missatges elèctrics.','Les <b>neurones</b> transmeten els impulsos nerviosos.','nervis|glòbuls'],
  ['Quina part de l\'encèfal pensa, recorda i dona les ordres dels moviments voluntaris?','cervell','És la part més grossa de l\'encèfal.','El <b>cervell</b> és el centre de la intel·ligència i la memòria.','cerebel|medul·la espinal'],
  ['Quina part de l\'encèfal coordina els moviments i ens ajuda a mantenir l\'equilibri?','cerebel','Té un nom semblant al cervell.','El <b>cerebel</b> és a la part de darrere i de baix del cap.','cervell|tronc encefàlic'],
  ['Quin òrgan del sistema nerviós central és dins la columna vertebral?','medul·la espinal|medul·la','Baixa per dins l\'esquena.','La <b>medul·la espinal</b> uneix l\'encèfal amb els nervis i controla els reflexos.','cerebel|nervis'],
  ['Quin os protegeix l\'encèfal?','crani','És l\'os del cap.','El <b>crani</b> és una capsa d\'os que protegeix l\'encèfal.','columna vertebral'],
  ['Com es diu un acte molt ràpid i involuntari, com apartar la mà d\'una cosa que crema?','acte reflex|reflex','No hi pensam: passa sol.','Els <b>actes reflexos</b> els controla la medul·la espinal.','acte voluntari|voluntari'],
  ['Com es diu un acte que decidim fer, com escriure o xutar una pilota?','acte voluntari|voluntari','El decideix el cervell.','Els <b>actes voluntaris</b> els ordena el cervell.','acte reflex|reflex'],
  ['Com es diuen els cordons que porten la informació entre el sistema nerviós central i la resta del cos?','nervis|nervi','Formen el sistema nerviós perifèric.','Els <b>nervis</b> sensitius porten la informació i els motors porten les ordres.','neurones|tendons'],
  ['Quina part de l\'encèfal controla el batec del cor i la respiració sense que hi pensem?','tronc encefàlic|bulb raquidi|tronc','Uneix el cervell amb la medul·la.','El <b>tronc encefàlic</b> controla funcions automàtiques com la respiració.','cerebel|cervell',1],
  ['Com es diu la prolongació llarga de la neurona per on surt el missatge?','axó','És una paraula de tres lletres.','L\'<b>axó</b> porta l\'impuls nerviós cap a una altra neurona o un múscul; les dendrites el reben.','dendrites|dendrita',1]]);

/* ---------- Els sentits ---------- */
SK.md_sentits=mdSkill('Els òrgans dels sentits','Se','md_sentits',
 ['Els <b>sentits</b> capten informació de l\'exterior gràcies a uns <b>receptors</b> i l\'envien al cervell pels nervis.','<b>Vista</b> (ull): la llum entra per la <b>pupil·la</b>, que l\'<b>iris</b> fa més gran o més petita; el <b>cristal·lí</b> enfoca la imatge sobre la <b>retina</b>, i el <b>nervi òptic</b> la porta al cervell.','<b>Oïda</b> (orella): el so fa vibrar el <b>timpà</b> i tres ossets (<b>martell, enclusa i estrep</b>); el <b>cargol</b> (còclea) envia el missatge al cervell. L\'orella interna també controla l\'<b>equilibri</b>.','<b>Olfacte</b> (nas: la pituïtària capta les olors), <b>gust</b> (llengua: les papil·les gustatives capten els sabors dolç, salat, àcid i amarg) i <b>tacte</b> (pell: capta la pressió, el fred, la calor i el dolor).'],
 [['Com es diu el forat negre del centre de l\'ull per on entra la llum?','pupil·la|nineta','Es fa petita quan hi ha molta llum.','La <b>pupil·la</b> és un forat; l\'iris, la part de color, en canvia la mida.','iris'],
  ['Com es diu la part de color de l\'ull?','iris','Pot ser blava, verda, marró...','L\'<b>iris</b> fa més gran o més petita la pupil·la.','pupil·la|retina'],
  ['Com es diu la capa del fons de l\'ull on es forma la imatge?','retina','Té cèl·lules sensibles a la llum.','A la <b>retina</b> es forma la imatge, que el nervi òptic porta al cervell.','còrnia|iris'],
  ['Quina lent de dins l\'ull enfoca la imatge?','cristal·lí','Té nom de vidre.','El <b>cristal·lí</b> és una lent que enfoca la imatge sobre la retina.','retina|còrnia'],
  ['Quina membrana de l\'orella vibra quan hi arriba el so?','timpà','És com la pell d\'un tambor.','El so fa vibrar el <b>timpà</b> i després els ossets.','cargol|còclea'],
  ['Quin sentit ens fa notar si una cosa és dolça, salada, àcida o amarga?','gust','Es fa amb la llengua.','El <b>gust</b> funciona gràcies a les papil·les gustatives.','olfacte|tacte'],
  ['Quin és l\'òrgan del sentit del tacte?','pell','Cobreix tot el cos.','La <b>pell</b> té receptors de pressió, temperatura i dolor.','mans|dits'],
  ['A més de sentir, quina altra cosa controla l\'orella interna?','equilibri|l\'equilibri','Si gires molt, et mareges.','L\'orella interna ens ajuda a mantenir l\'<b>equilibri</b>.','tacte'],
  ['Quin nervi porta la imatge de l\'ull fins al cervell?','nervi òptic|òptic','«Òptic» vol dir de la vista.','El <b>nervi òptic</b> uneix la retina amb el cervell.','nervi auditiu|auditiu'],
  ['Com es diu l\'os més petit del cos, que és dins l\'orella?','estrep','Té nom d\'una peça de la sella del cavall.','L\'<b>estrep</b> fa uns 3 mil·límetres. Els altres ossets són el martell i l\'enclusa.','martell|enclusa',1],
  ['Com es diu la mucosa del nas que capta les olors?','pituïtària','Comença per P.','La <b>pituïtària</b> té cèl·lules que capten les olors.','',1]]);

/* ---------- L'aparell locomotor ---------- */
const OSSOS=[['el crani','protegeix l\'encèfal','crani'],['les costelles','protegeixen el cor i els pulmons','costelles|costella'],['la columna vertebral','sosté el cos i protegeix la medul·la espinal','columna vertebral|columna|espinada'],['el fèmur','és l\'os de la cuixa, el més llarg del cos','fèmur'],['la ròtula','és l\'os petit de davant del genoll','ròtula'],['l\'húmer','és l\'os del braç, entre l\'espatla i el colze','húmer'],['la clavícula','uneix l\'esternó amb l\'espatla','clavícula'],['l\'esternó','és l\'os pla del mig del pit, on s\'uneixen les costelles','esternó'],['la tíbia','és l\'os gros de la cama, entre el genoll i el turmell','tíbia']];
SK.md_locomotor=mdMix(mdSkill('L\'aparell locomotor','Lo','md_locomotor',
 ['L\'<b>aparell locomotor</b> ens permet moure\'ns. Està format per l\'<b>esquelet</b> (ossos i articulacions) i els <b>músculs</b>.','L\'esquelet d\'un adult té <b>206 ossos</b>. Funcions: <b>sostenir</b> el cos, <b>protegir</b> els òrgans (el crani protegeix l\'encèfal; les costelles, el cor i els pulmons) i permetre el <b>moviment</b>.','Les <b>articulacions</b> són les unions entre ossos: <b>mòbils</b> (genoll, colze), <b>semimòbils</b> (vèrtebres) i <b>fixes</b> (crani). Els <b>lligaments</b> uneixen els ossos entre ells.','Tenim més de 600 <b>músculs</b>. Els <b>tendons</b> uneixen els músculs als ossos. Els músculs només estiren: per això treballen per parelles (el <b>bíceps</b> doblega el braç i el <b>tríceps</b> l\'estira).'],
 [['Quants ossos té l\'esquelet d\'una persona adulta?','206','Són una mica més de 200.','Un adult té <b>206 ossos</b>.','650'],
  ['Com es diu la unió entre dos ossos?','articulació|articulacions','El genoll n\'és una.','Les <b>articulacions</b> uneixen els ossos i en permeten el moviment.','tendó|lligament'],
  ['Com es diuen els cordons resistents que uneixen els músculs als ossos?','tendons|tendó','El d\'Aquil·les és al taló.','Els <b>tendons</b> uneixen músculs i ossos.','lligaments|lligament'],
  ['Com es diuen les bandes que uneixen els ossos entre si a les articulacions?','lligaments|lligament','No els confonguis amb els tendons.','Els <b>lligaments</b> uneixen ossos amb ossos.','tendons|tendó'],
  ['Quin múscul del braç es contreu per doblegar el colze?','bíceps','És a la part de davant del braç.','El <b>bíceps</b> doblega el braç; el tríceps l\'estira.','tríceps'],
  ['Quin múscul del braç es contreu per estirar el braç?','tríceps','És a la part de darrere del braç.','El <b>tríceps</b> estira el braç.','bíceps'],
  ['Com es diu una articulació que no es mou, com les del crani?','fixa|articulació fixa|fixes','Els ossos estan soldats.','Les articulacions <b>fixes</b> no permeten moviment.','mòbil|semimòbil',1],
  ['Com es diuen els ossos que formen la columna vertebral?','vèrtebres|vèrtebra','N\'hi ha 33 o 34.','La columna està formada per <b>vèrtebres</b>.','costelles',1]]),
 ()=>{const[n,f,a]=pick(OSSOS);return{text:`Quin os ${f}?`,fields:[{label:'Os',txt:a.split('|'),loose:true,wide:true}],vis:null,
  hints:['Pensa en la part del cos on és.',`Comença per «${n.replace(/^(el|la|les|l') ?/,'')[0].toUpperCase()}».`],steps:[`L'os que ${f} és <b>${n}</b>.`],
  err:v=>OSSOS.some(o=>o[0]!==n&&o[2].split('|').map(fold).includes(fold(v[0])))?'md_locomotor':null}},.4);

/* ---------- La reproducció ---------- */
SK.md_reproduccio=mdSkill('La reproducció humana','Rp','md_reproduccio',
 ['La <b>reproducció</b> és la funció vital que permet tenir descendents. Les persones tenim <b>reproducció sexual</b>: un nou ésser es forma a partir de dues cèl·lules, l\'<b>òvul</b> (de la mare) i l\'<b>espermatozoide</b> (del pare).','Les cèl·lules reproductores es fabriquen als <b>ovaris</b> (aparell reproductor femení) i als <b>testicles</b> (aparell reproductor masculí).','La unió de l\'òvul i l\'espermatozoide és la <b>fecundació</b>, i forma el <b>zigot</b>. El nou ésser creix dins l\'<b>úter</b> durant l\'<b>embaràs</b>, uns <b>9 mesos</b>. Rep l\'aliment i l\'oxigen per la <b>placenta</b> i el <b>cordó umbilical</b>. El naixement és el <b>part</b>.','Etapes de la vida: infància, <b>adolescència</b>, edat adulta i vellesa. A la <b>pubertat</b> (cap als 10-14 anys) el cos canvia: creixem molt, ens surt pèl, canvia la veu... Cada persona hi arriba al seu ritme i tots els canvis són normals.'],
 [['Com es diu la cèl·lula reproductora femenina?','òvul','Es forma als ovaris.','L\'<b>òvul</b> és la cèl·lula reproductora femenina.','espermatozoide'],
  ['Com es diu la cèl·lula reproductora masculina?','espermatozoide','Es forma als testicles i té una cua.','L\'<b>espermatozoide</b> és la cèl·lula reproductora masculina.','òvul'],
  ['Com es diu la unió de l\'òvul i l\'espermatozoide?','fecundació','Després s\'inicia l\'embaràs.','La <b>fecundació</b> forma el zigot, la primera cèl·lula del nou ésser.','pol·linització|part'],
  ['Com es diu la primera cèl·lula del nou ésser, que es forma en la fecundació?','zigot','Comença per Z.','El <b>zigot</b> es divideix moltes vegades i forma l\'embrió.','òvul|embrió'],
  ['En quin òrgan de la mare es desenvolupa el bebè durant l\'embaràs?','úter|matriu','També se\'n diu matriu.','El bebè creix dins l\'<b>úter</b>.','ovaris|ovari'],
  ['Quants mesos dura més o menys l\'embaràs?','9|nou','És una mica menys d\'un any.','L\'embaràs dura uns <b>9 mesos</b> (unes 40 setmanes).','12'],
  ['Per quin tub rep el bebè l\'aliment i l\'oxigen de la mare?','cordó umbilical|cordó','En néixer es talla i queda el melic.','El <b>cordó umbilical</b> uneix el bebè amb la placenta.','placenta'],
  ['Com es diu el moment del naixement del bebè?','part','Es diu «estar de...».','El <b>part</b> és la sortida del bebè de l\'úter de la mare.','fecundació'],
  ['Com es diu l\'etapa en què el cos de l\'infant comença a canviar per fer-se adult?','pubertat','Comença cap als 10-14 anys.','A la <b>pubertat</b> el cos canvia gràcies a les hormones.','vellesa|infància'],
  ['Com es diu l\'etapa de la vida entre la infància i l\'edat adulta?','adolescència','Comença amb la pubertat.','L\'<b>adolescència</b> és l\'etapa de canvis físics i emocionals.','infància|vellesa'],
  ['Quins òrgans de l\'aparell reproductor femení fabriquen els òvuls?','ovaris|ovari','N\'hi ha dos.','Els <b>ovaris</b> fabriquen els òvuls.','úter|testicles',1],
  ['Com es diuen les substàncies que fabrica el cos i que provoquen els canvis de la pubertat?','hormones|hormona','Són missatgers químics.','Les <b>hormones</b> fan que el cos canviï a la pubertat.','',1]]);

/* ---------- La salut ---------- */
SK.md_salut=mdSkill('La salut i els hàbits saludables','Sa','md_salut',
 ['La <b>salut</b> és estar bé del cos, de la ment i amb els altres. La cuidam amb <b>hàbits saludables</b>: menjar bé, fer exercici, dormir prou (uns 9-10 hores als 11-12 anys), la higiene i passar temps amb els amics.','<b>Dieta equilibrada</b>: menjar de tot i en la quantitat adequada. Els nutrients són els <b>glúcids</b> (energia: pa, pasta, arròs), els <b>lípids</b> (greixos: oli, mantega), les <b>proteïnes</b> (per créixer: carn, peix, ous, llegums), les <b>vitamines</b> i els <b>minerals</b> (fruita i verdura) i l\'<b>aigua</b>. La dieta mediterrània és molt saludable.','Les <b>malalties infeccioses</b> les causen microbis (bacteris, virus, fongs) i es poden contagiar, com la grip. Les <b>no infeccioses</b> no es contagien, com la diabetis o una al·lèrgia.','Les <b>vacunes</b> ens preparen les defenses per no emmalaltir. Els <b>antibiòtics</b> només serveixen contra els <b>bacteris</b>, no contra els virus, i només els ha de receptar el metge. En una emergència, cridam al <b>112</b>.'],
 [['Quin nutrient ens dona sobretot energia i es troba al pa, la pasta i l\'arròs?','glúcids|glúcid|hidrats de carboni|carbohidrats','També se\'n diuen hidrats de carboni.','Els <b>glúcids</b> ens donen l\'energia per moure\'ns.','proteïnes|lípids'],
  ['Quin nutrient serveix sobretot per créixer i es troba a la carn, el peix, els ous i els llegums?','proteïnes|proteïna','Formen els músculs.','Les <b>proteïnes</b> serveixen per construir i reparar el cos.','glúcids|lípids|vitamines'],
  ['Com es diuen els nutrients que són greixos, com l\'oli o la mantega?','lípids|lípid|greixos','També s\'anomenen greixos.','Els <b>lípids</b> són una reserva d\'energia.','glúcids|proteïnes'],
  ['Com es diuen les malalties que es contagien d\'una persona a una altra?','infeccioses|malalties infeccioses|contagioses','Les causen microbis.','Les <b>malalties infeccioses</b> les causen bacteris, virus o fongs.','no infeccioses'],
  ['Quin medicament ens prepara les defenses per no agafar una malaltia?','vacuna|vacunes','Se\'ns posa amb una injecció quan som sans.','Les <b>vacunes</b> ensenyen al cos a defensar-se d\'un microbi.','antibiòtic|antibiòtics'],
  ['Contra quin tipus de microbis serveixen els antibiòtics?','bacteris|bacteri','No serveixen contra els virus.','Els antibiòtics només maten <b>bacteris</b>. Contra la grip o el refredat (virus) no serveixen.','virus|fongs'],
  ['A quin número de telèfon cridam en una emergència?','112','Són tres xifres.','El <b>112</b> és el telèfon d\'emergències de tota la Unió Europea.','091|061'],
  ['Com es diu la dieta tradicional dels països de la nostra mar, amb oli d\'oliva, fruita, verdura, peix i llegums?','dieta mediterrània|mediterrània','Té el nom de la mar.','La <b>dieta mediterrània</b> és una de les més saludables del món.','',0],
  ['Quin microbi molt petit, que no és ni tan sols una cèl·lula, causa la grip o el refredat?','virus','No el maten els antibiòtics.','Els <b>virus</b> causen la grip, el refredat o la COVID-19.','bacteri|bacteris'],
  ['Quina malaltia no infecciosa fa que el cos no controli bé el sucre de la sang?','diabetis','Les persones que la tenen sovint es posen insulina.','La <b>diabetis</b> no es contagia.','',1]],
 {});

/* ---------- Els ecosistemes de les Illes Balears ---------- */
SK.md_ecobal=mdSkill('Els ecosistemes de les Illes Balears','Eb','md_ecobal',
 ['A les Illes hi ha ecosistemes <b>terrestres</b> (alzinars, pinars, garriga, zones humides com s\'Albufera) i <b>marins</b> (praderies de posidònia, fons rocosos).','La <b>posidònia</b> és una <b>planta</b> marina (no una alga!): té arrels, tija, fulles, flors i fruits. Les seves praderies fan oxigen, aclareixen l\'aigua i protegeixen les platges. Està protegida i no s\'hi pot fondejar.','Una <b>espècie endèmica</b> només viu en un lloc del món. Endemismes de les Balears: el <b>ferreret</b> (un gripau de la Serra de Tramuntana), la <b>sargantana balear</b>, la <b>baldritja balear</b> o virot (un ocell marí). El <b>voltor negre</b> viu a la Serra de Tramuntana.','Amenaces: els incendis, la contaminació, les <b>espècies invasores</b> (com la serp a Eivissa), el malbaratament de l\'aigua i l\'excés de construcció. Per protegir-los hi ha <b>espais naturals protegits</b>: el Parc Nacional de Cabrera, els parcs naturals (s\'Albufera, sa Dragonera, ses Salines) i la Reserva de la Biosfera de Menorca.'],
 [['Com es diu la planta marina que forma praderies sota la mar de les Balears?','posidònia|posidonia oceanica','No és una alga.','La <b>posidònia</b> és una planta amb flors i fruits.','alga|algues'],
  ['Com es diu una espècie que només viu en un lloc concret del món?','endèmica|endemisme|espècie endèmica','Comença per E.','Una espècie <b>endèmica</b> o un <b>endemisme</b> només viu en aquell lloc.','invasora|autòctona'],
  ['Com es diu una espècie que arriba d\'un altre lloc i perjudica les espècies d\'aquí?','invasora|espècie invasora','«Envaeix» el territori.','Les <b>espècies invasores</b> fan mal a les autòctones.','endèmica'],
  ['Quin gripau endèmic de Mallorca viu als torrents de la Serra de Tramuntana?','ferreret','Té el nom d\'un ofici amb ferro.','El <b>ferreret</b> és un endemisme de Mallorca en perill d\'extinció.','granota|salamandra'],
  ['Quin gran ocell rapinyaire, que menja carronya, viu a la Serra de Tramuntana?','voltor negre|voltor','És l\'ocell més gros de les Illes.','El <b>voltor negre</b> s\'ha recuperat gràcies a la protecció.','àguila|milà'],
  ['Com es diu el Parc Nacional de les Illes Balears, al sud de Mallorca?','Cabrera|Parc Nacional de Cabrera','És un arxipèlag petit.','El <b>Parc Nacional de Cabrera</b> és de 1991.','Dragonera|Albufera'],
  ['Quina illa és tota Reserva de la Biosfera des de 1993?','Menorca','És l\'illa més oriental.','<b>Menorca</b> és Reserva de la Biosfera.','Mallorca|Eivissa'],
  ['Com es diu el conjunt de matolls baixos (ullastres, mates, romaní) tan típic de les Illes?','garriga|màquia','Creix on hi ha poca aigua.','La <b>garriga</b> és un ecosistema mediterrani de matolls.','alzinar|pinar'],
  ['Com es diu el bosc d\'alzines, típic de la Serra de Tramuntana?','alzinar','Ve del nom de l\'arbre.','L\'<b>alzinar</b> és el bosc mediterrani original de moltes zones de Mallorca.','pinar',1],
  ['Quin ocell marí endèmic de les Balears, també dit virot, està en perill crític d\'extinció?','baldritja balear|baldritja|virot','Té dos noms.','La <b>baldritja balear</b> (virot) cria als penya-segats de les Illes.','gavina',1]]);

/* ---------- Les mescles ---------- */
const MIX=[['aigua i sorra','filtració|filtrar|filtre|decantació|decantar','la sorra no es dissol: un filtre (o deixar-la reposar) la separa','filtració'],['aigua amb sal dissolta','evaporació|evaporar|destil·lació|destil·lar','la sal està dissolta: cal evaporar l\'aigua i la sal queda al fons (així es fa a les salines)','evaporació'],['llimadures de ferro i serradures','imantació|imant|amb un imant|separació magnètica','el ferro és atret per l\'imant i la fusta no','imantació'],['aigua i oli','decantació|decantar|embut de decantació','no es mesclen: l\'oli sura i es pot separar amb compte','decantació'],['cigrons i arròs','tamisatge|tamisar|garbellat|garbellar|sedàs|colador','tenen mides diferents: un sedàs deixa passar l\'arròs i atura els cigrons','tamisatge'],['clips de ferro i botons de plàstic','imantació|imant|amb un imant|separació magnètica','els clips de ferro són atrets per un imant','imantació'],['aigua amb sucre dissolt','evaporació|evaporar|destil·lació|destil·lar','el sucre està dissolt: si l\'aigua s\'evapora, el sucre queda al fons','evaporació'],['cafè mòlt i aigua','filtració|filtrar|filtre','el cafè mòlt no es dissol del tot i el filtre l\'atura','filtració'],['pedretes i farina','tamisatge|tamisar|garbellat|garbellar|sedàs|colador','la farina passa pels forats del sedàs i les pedretes no','tamisatge']];
const METODES=['filtració','filtrar','decantació','decantar','evaporació','evaporar','imantació','imant','tamisatge','tamisar','garbellar','sedàs','destil·lació'];
SK.md_mescles=mdMix(mdSkill('Les mescles i com separar-les','Mx','md_mescles',
 ['Una <b>substància pura</b> té un sol component (l\'aigua destil·lada, l\'or). Una <b>mescla</b> té dos o més components.','<b>Mescles heterogènies</b>: se\'n distingeixen els components (aigua i sorra, una amanida). <b>Mescles homogènies</b> o <b>dissolucions</b>: no se\'n distingeixen els components (aigua amb sal). A una dissolució, el <b>solut</b> és la substància que es dissol (la sal) i el <b>dissolvent</b>, on es dissol (l\'aigua).','Mètodes de separació: <b>filtració</b> (un filtre atura el sòlid que no s\'ha dissolt), <b>decantació</b> (deixar reposar i separar: aigua i oli), <b>evaporació</b> (l\'aigua s\'evapora i queda el sòlid dissolt), <b>imantació</b> (un imant separa el ferro) i <b>tamisatge</b> (un sedàs separa sòlids de mides diferents).','A les <b>salines</b> d\'Eivissa, Formentera i el sud de Mallorca s\'obté la sal per evaporació de l\'aigua de la mar.'],
 [['Com es diu una mescla en què NO es poden distingir els components, com l\'aigua amb sal?','homogènia|mescla homogènia|dissolució','També se\'n diu dissolució.','Una mescla <b>homogènia</b> o dissolució sembla una sola substància.','heterogènia'],
  ['Com es diu una mescla en què SÍ es poden distingir els components, com una amanida?','heterogènia|mescla heterogènia','«Hetero» vol dir diferent.','En una mescla <b>heterogènia</b> es veuen els components.','homogènia|dissolució'],
  ['En una dissolució d\'aigua amb sucre, com es diu el sucre?','solut','És la substància que es dissol.','El <b>solut</b> és el que es dissol; l\'aigua és el dissolvent.','dissolvent'],
  ['En una dissolució d\'aigua amb sal, com es diu l\'aigua?','dissolvent','És on es dissol la sal.','El <b>dissolvent</b> és la substància on es dissol el solut.','solut'],
  ['Com es diu una substància formada per un sol component, com l\'or o l\'aigua destil·lada?','substància pura|pura','No és una mescla.','Una <b>substància pura</b> té un sol component.','mescla'],
  ['Com es diuen els llocs vora la mar on s\'obté la sal evaporant l\'aigua?','salines|salina','Ses ... d\'Eivissa són famoses.','A les <b>salines</b>, el sol i el vent evaporen l\'aigua i queda la sal.','',1]]),
 lv=>{const[m,a,ex,nom]=pick(MIX);return{text:`Tenim una mescla de <b>${m}</b>. Quin mètode faries servir per separar-ne els components?`,fields:[{label:'Mètode de separació',txt:a.split('|'),loose:true,wide:true}],vis:null,
  hints:['Pensa: el sòlid està dissolt o no? Algun component és de ferro? Tenen mides diferents? Es mesclen els líquids?',`El mètode comença per «${nom[0].toUpperCase()}».`],steps:[`A la mescla de ${m}, ${ex}.`,`El mètode és la <b>${nom}</b>.`],
  err:v=>{const x=fold(v[0]);return METODES.map(fold).includes(x)&&!a.split('|').map(fold).includes(x)?'md_mescles':null}}},.6);

/* ---------- Els canvis de la matèria ---------- */
const CANVIS=[['Cremam un tros de paper i es converteix en cendres i fum','combustió','el paper reacciona amb l\'oxigen i desprèn llum i calor'],['Un clau de ferro deixat a la intempèrie es rovella','oxidació','el ferro reacciona amb l\'oxigen i la humitat i es forma rovell'],['La cadena d\'una bicicleta que ha estat a la pluja es posa de color taronja','oxidació','el ferro de la cadena reacciona amb l\'oxigen i la humitat'],['Una poma tallada es posa marró','oxidació','la poma reacciona amb l\'oxigen de l\'aire'],['La llet es converteix en iogurt gràcies a uns bacteris','fermentació','els bacteris transformen el sucre de la llet'],['La massa del pa puja gràcies al llevat','fermentació','el llevat transforma els sucres de la farina i fa gas'],['El suc de raïm es converteix en vi','fermentació','els llevats transformen el sucre del raïm'],['El gas butà crema als fogons de la cuina','combustió','el gas reacciona amb l\'oxigen i desprèn llum i calor'],['Encenem una espelma','combustió','la cera crema amb l\'oxigen i fa llum i calor']];
const CQN=['combustió','oxidació','fermentació'];
SK.md_canvis=mdMix(mdSkill('Els canvis físics i químics','Cq','md_canvis',
 ['Als <b>canvis físics</b> la matèria canvia de forma, de mida o d\'estat, però <b>continua essent la mateixa substància</b>: trencar, doblegar, dissoldre, fondre...','Als <b>canvis químics</b> (o <b>reaccions químiques</b>) unes substàncies es transformen en <b>substàncies noves</b>, diferents. Exemples: la <b>combustió</b> (cremar), l\'<b>oxidació</b> (el ferro es rovella), la <b>fermentació</b> (pa, iogurt, vi) i la cocció dels aliments.','La <b>combustió</b> necessita tres coses (el triangle del foc): <b>combustible</b> (fusta, gas...), <b>comburent</b> (l\'oxigen de l\'aire) i <b>calor</b>. Si en llevam una, el foc s\'apaga.','Per evitar l\'oxidació, el ferro es pinta o es cobreix amb altres metalls.'],
 [['Com es diu el canvi químic en què una substància crema i desprèn llum i calor?','combustió','Necessita oxigen.','La <b>combustió</b> és una reacció química amb l\'oxigen que fa llum i calor.','oxidació|fermentació'],
  ['Com es diu el canvi químic que fa que el ferro es rovelli?','oxidació','Hi intervé l\'oxigen de l\'aire i la humitat.','L\'<b>oxidació</b> forma rovell sobre el ferro.','combustió'],
  ['Com es diu el canvi químic que fan els llevats i els bacteris quan fem pa o iogurt?','fermentació','Hi participen microorganismes.','La <b>fermentació</b> transforma els sucres en altres substàncies.','oxidació|combustió'],
  ['Quin gas de l\'aire és el comburent necessari perquè hi hagi foc?','oxigen','És el mateix que respiram.','L\'<b>oxigen</b> és el comburent.','diòxid de carboni|nitrogen'],
  ['Com es diu el material que crema en un foc, com la fusta o el gas?','combustible','Al triangle del foc, el costat que «crema».','El <b>combustible</b> és el material que crema.','comburent'],
  ['Si tapam una espelma amb un got, s\'apaga. Quin element del triangle del foc li falta?','oxigen|comburent','Què hi ha a l\'aire que es gasta?','Dins el got s\'acaba l\'<b>oxigen</b> (el comburent) i el foc s\'apaga.','calor|combustible',1]]),
 ()=>{const[t,c,why]=pick(CANVIS);return{text:`${t}. Quin canvi químic és?`,fields:[{label:'Nom del canvi químic',txt:[c],loose:true,wide:true}],vis:null,
  hints:['Hi ha foc? Hi intervé l\'oxigen i la humitat sobre un metall o un aliment? Hi treballen microorganismes (llevats, bacteris)?',`Comença per «${c[0].toUpperCase()}».`],steps:[`En aquest cas, ${why}.`,`Per tant, és una <b>${c}</b>.`],
  err:v=>CQN.some(n=>n!==c&&fold(n)===fold(v[0]))?'md_canvis':null}},.5);

/* ---------- Massa, volum i densitat ---------- */
SK.md_densitat=mdMix(mdSkill('Massa, volum i densitat','Ds','md_densitat',
 ['La <b>massa</b> és la quantitat de matèria d\'un cos. Es mesura amb una balança, en <b>quilograms (kg)</b> o <b>grams (g)</b>. 1 kg = 1.000 g.','El <b>volum</b> és l\'espai que ocupa un cos. Es mesura en <b>litres (L)</b>, <b>mil·lilitres (mL)</b> o <b>centímetres cúbics (cm³)</b>. 1 L = 1.000 mL, i 1 mL = 1 cm³.','La <b>densitat</b> és la massa que hi ha en cada unitat de volum: <b>densitat = massa : volum</b>. Es mesura en g/cm³. L\'aigua té una densitat d\'<b>1 g/cm³</b>.','Un objecte <b>sura</b> a l\'aigua si la seva densitat és menor que 1 g/cm³ (la fusta, el suro, l\'oli) i s\'enfonsa si és major (el ferro, una pedra).'],
 [['Amb quin instrument mesuram la massa?','balança|bàscula','Té dos plats o una pantalla.','La massa es mesura amb una <b>balança</b>.','proveta|termòmetre'],
  ['Quants grams té un quilogram?','1000|mil|1.000','«Quilo» vol dir mil.','1 kg = <b>1.000 g</b>.','100'],
  ['Quants mil·lilitres té un litre?','1000|mil|1.000','«Mil·li» vol dir mil·lèsima part.','1 L = <b>1.000 mL</b>.','100'],
  ['Quina és la densitat de l\'aigua, en g/cm³?','1|un','És el nombre més senzill.','L\'aigua té una densitat d\'<b>1 g/cm³</b>.','0|10'],
  ['Amb quin recipient graduat de laboratori es mesura el volum dels líquids?','proveta','És un tub alt amb rallades.','La <b>proveta</b> té marques en mL.','balança',1]]),
 lv=>{const dd=pick(lv>0?[2,4,5,8,12,15,25,27,78,113]:[5,8,15,20,25,30,40]);let V=pick([10,20,25,40,50,100,200]);while(dd*V%10)V=pick([10,20,40,50,100,200]);const d=dd/10,m=dd*V/10,ds=String(d).replace('.',','),t=Math.random(),obj=pick(['Un tros de metall','Una pedra','Un bloc de fusta','Una peça de plàstic','Un objecte misteriós']);
  if(t<.55||lv===0)return{text:`${obj} té una massa de <b>${m} g</b> i un volum de <b>${V} cm³</b>. Quina és la seva densitat (en g/cm³)?`,fields:[{label:'Densitat (g/cm³)',ans:R(m,V)}],vis:null,
   hints:['Densitat = massa : volum.',`Divideix ${m} entre ${V}.`],steps:['Densitat = massa : volum.',`${m} : ${V} = ${ds}.`,`La densitat és <b>${ds} g/cm³</b>. ${d<1?'Com que és menor que 1, sura a l\'aigua.':d>1?'Com que és major que 1, s\'enfonsa a l\'aigua.':'És igual que la de l\'aigua.'}`],
   err:v=>req(v[0],R(V,m))||req(v[0],R(m*V))?'md_densitat':null};
  if(t<.8)return{text:`Un material té una densitat de <b>${ds} g/cm³</b>. Quina massa tindrà un tros de <b>${V} cm³</b>?`,fields:[{label:'Massa (g)',ans:R(m)}],vis:null,
   hints:['Si densitat = massa : volum, aleshores massa = densitat × volum.',`Multiplica ${ds} × ${V}.`],steps:['Massa = densitat × volum.',`${ds} × ${V} = ${m}.`,`La massa és <b>${m} g</b>.`],err:v=>req(v[0],R(V*10,dd))?'md_densitat':null};
  return{text:`Un material té una densitat de <b>${ds} g/cm³</b>. Quin volum ocupa un tros de <b>${m} g</b>?`,fields:[{label:'Volum (cm³)',ans:R(V)}],vis:null,
   hints:['Si densitat = massa : volum, aleshores volum = massa : densitat.',`Divideix ${m} entre ${ds}.`],steps:['Volum = massa : densitat.',`${m} : ${ds} = ${V}.`,`El volum és <b>${V} cm³</b>.`],err:v=>req(v[0],R(m*dd,10))?'md_densitat':null}},.65);

/* ---------- El magnetisme ---------- */
SK.md_magnetisme=mdSkill('El magnetisme','Mg','md_magnetisme',
 ['Els <b>imants</b> atrauen alguns metalls: el <b>ferro</b>, el <b>níquel</b> i el <b>cobalt</b> (i l\'acer, que té ferro). Són materials <b>magnètics</b>. La fusta, el plàstic, el vidre, el coure o l\'alumini no són atrets.','Tot imant té dos <b>pols</b>: el <b>nord</b> i el <b>sud</b>. Els pols <b>iguals es repel·leixen</b> i els pols <b>diferents s\'atrauen</b>. Si partim un imant, cada tros torna a tenir dos pols.','La <b>Terra</b> es comporta com un imant gegant. Per això l\'agulla imantada de la <b>brúixola</b> sempre assenyala el nord.','Un <b>electroimant</b> és un imant que funciona amb electricitat: un cable enrotllat al voltant d\'un clau de ferro. Només és imant quan hi passa el corrent (grues de ferralla, timbres, motors).'],
 [['Quin aparell té una agulla imantada que assenyala el nord?','brúixola','La feien servir els navegants.','La <b>brúixola</b> s\'orienta amb el magnetisme de la Terra.','imant|rellotge'],
  ['Escriu el nom d\'un metall que sigui atret pels imants.','ferro|níquel|cobalt|acer','Els claus en són.','El <b>ferro</b>, el níquel i el cobalt són magnètics.','coure|alumini|or|plata'],
  ['Què fan dos pols iguals de dos imants: s\'atrauen o es repel·leixen?','es repel·leixen|repel·leixen|es repel·len|repel·len','Nord amb nord...','Els pols <b>iguals es repel·leixen</b>.','s\'atrauen|atrauen'],
  ['Què fan el pol nord d\'un imant i el pol sud d\'un altre: s\'atrauen o es repel·leixen?','s\'atrauen|atrauen|s\'atreuen','Són diferents...','Els pols <b>diferents s\'atrauen</b>.','es repel·leixen|repel·leixen'],
  ['Com es diuen els dos extrems d\'un imant, on la força és més gran?','pols|pol','Es diuen nord i sud.','Els <b>pols</b> d\'un imant són el nord i el sud.','cares|puntes'],
  ['Si partim un imant per la meitat, quants pols tindrà cada tros?','2|dos','Torna a tenir nord i sud.','Cada tros és un imant nou amb <b>2 pols</b>.','1'],
  ['Com es diu un imant que funciona amb corrent elèctric?','electroimant','És la unió d\'«electricitat» i «imant».','Un <b>electroimant</b> només atrau quan hi passa el corrent.','pila|motor'],
  ['Quin planeta es comporta com un imant gegant?','Terra|la Terra','Hi vivim.','La <b>Terra</b> té un camp magnètic que orienta les brúixoles.','Mart|Sol',1]]);

/* ---------- Les màquines ---------- */
SK.md_maquines=mdMix(mdSkill('Les màquines i la palanca','Mq','md_maquines',
 ['Les <b>màquines</b> ens ajuden a fer feines amb menys esforç. Les <b>màquines simples</b> tenen poques peces: la <b>palanca</b>, la <b>politja</b>, el <b>pla inclinat</b>, la <b>roda</b>, la <b>falca</b> i el <b>cargol</b>. Les <b>màquines compostes</b> en combinen moltes (la bicicleta, el cotxe).','Una <b>palanca</b> és una barra que gira sobre un <b>punt de suport</b>. Hi actuen la <b>potència</b> (la força que feim) i la <b>resistència</b> (el pes que volem moure).','Llei de la palanca: <b>potència × braç de potència = resistència × braç de resistència</b>. Com més lluny del punt de suport empenyem, menys força hem de fer.','Tipus de palanques: <b>1r gènere</b>, el punt de suport al mig (balancí, tisores, alicates); <b>2n gènere</b>, la resistència al mig (carretó, trencanous); <b>3r gènere</b>, la potència al mig (pinces, canya de pescar).'],
 [['Com es diu la màquina simple formada per una roda amb una corda que serveix per pujar pesos?','politja','N\'hi ha als pous.','La <b>politja</b> canvia la direcció de la força.','palanca|roda'],
  ['Com es diu la màquina simple que és una rampa per pujar objectes amb menys esforç?','pla inclinat|rampa','És una superfície inclinada.','El <b>pla inclinat</b> fa el camí més llarg però més fàcil.','palanca'],
  ['Com es diu el punt sobre el qual gira una palanca?','punt de suport|fulcre|suport','En un balancí, és al mig.','La palanca gira sobre el <b>punt de suport</b> (fulcre).','potència|resistència'],
  ['En una palanca, com es diu la força que feim nosaltres?','potència','La resistència és el pes que movem.','La <b>potència</b> és la força que aplicam.','resistència'],
  ['En una palanca, com es diu el pes o la força que volem vèncer?','resistència','És el contrari de la potència.','La <b>resistència</b> és la càrrega que volem moure.','potència'],
  ['De quin gènere és una palanca com el balancí, amb el punt de suport al mig?','primer|1r|primer gènere|1','Mira què hi ha al mig.','El balancí és una palanca de <b>1r gènere</b>.','segon|tercer|2n|3r'],
  ['De quin gènere és un carretó, amb la resistència al mig?','segon|2n|segon gènere|2','La càrrega és entre la roda i les mans.','El carretó és una palanca de <b>2n gènere</b>.','primer|tercer|1r|3r'],
  ['De quin gènere són unes pinces, amb la potència al mig?','tercer|3r|tercer gènere|3','Les premem pel mig.','Les pinces són una palanca de <b>3r gènere</b>.','primer|segon|1r|2n',1],
  ['Com es diu una màquina formada per moltes màquines simples, com la bicicleta?','màquina composta|composta','És el contrari de simple.','La bicicleta és una <b>màquina composta</b>: té rodes, palanques, engranatges...','simple',1]]),
 lv=>{const bp=rnd(2,6),br=rnd(1,Math.min(3,bp-1)),P=rnd(1,8)*5*br,Rr=P*bp/br;
  if(lv>0&&Math.random()<.4)return{text:`Amb una palanca volem aixecar una pedra de <b>${Rr} kg</b> que és a <b>${br} m</b> del punt de suport. Si només podem fer una força de <b>${P} kg</b>, a quina distància del punt de suport hem d'empènyer?`,fields:[{label:'Braç de potència (m)',ans:R(bp)}],vis:null,
   hints:['Potència × braç de potència = resistència × braç de resistència.',`${P} × ? = ${Rr} × ${br} = ${Rr*br}.`],steps:[`Resistència × braç de resistència = ${Rr} × ${br} = ${Rr*br}.`,`${P} × ? = ${Rr*br} → ? = ${Rr*br} : ${P} = ${bp}.`,`Hem d'empènyer a <b>${bp} m</b> del punt de suport.`]};
  return{text:`Amb una palanca volem aixecar una pedra de <b>${Rr} kg</b>. La pedra és a <b>${br} m</b> del punt de suport i nosaltres empenyem a <b>${bp} m</b>. Quina força (potència) hem de fer, en kg?`,fields:[{label:'Potència (kg)',ans:R(P)}],vis:null,
   hints:['Potència × braç de potència = resistència × braç de resistència.',`? × ${bp} = ${Rr} × ${br}.`],steps:[`Resistència × braç de resistència = ${Rr} × ${br} = ${Rr*br}.`,`Potència = ${Rr*br} : ${bp} = ${P}.`,`Hem de fer una força de <b>${P} kg</b>: menys que el pes de la pedra perquè empenyem més lluny del punt de suport.`],
   err:v=>Rr*bp/br!==P&&req(v[0],R(Rr*bp,br))?'md_palanca':null}},.45);

